// Port of https://codepen.io/shingidad/pen/jEPxMgW (MIT via CodePen).
// The original iChannel0 is Vel's IN(): the composited layers below.
// Original iMouse center is Vel layer position (toUV(vec2(0))).
vec4 fx(){
  vec2 uv=vUv;
  vec2 center=toUV(vec2(0.0));
  vec2 m2=uv-center;
  float roundedBox=pow(abs(m2.x*uRes.x/uRes.y),6.0)+pow(abs(m2.y),6.0);
  float scale=pow(max(p_size,0.01),6.0);
  roundedBox/=scale;
  float rb1=clamp((1.0-roundedBox*10000.0)*8.0,0.0,1.0);
  float rb2=clamp((0.95-roundedBox*9500.0)*16.0,0.0,1.0)-clamp((0.9-roundedBox*9500.0)*16.0,0.0,1.0);
  float rb3=clamp((1.5-roundedBox*11000.0)*2.0,0.0,1.0)-clamp((1.0-roundedBox*11000.0)*2.0,0.0,1.0);
  float transition=smoothstep(0.0,1.0,rb1+rb2);
  vec4 base=IN(uv);
  if(transition<=0.0)return base;
  // The original lens formula is centered on the viewport, not the mouse.
  vec2 lens=(uv-0.5)*(1.0-roundedBox*5000.0)+0.5;
  vec4 glass=vec4(0.0); float total=0.0;
  for(int x=-4;x<=4;x++){for(int y=-4;y<=4;y++){
    vec2 offset=vec2(float(x),float(y))*0.5/uRes;
    glass+=IN(clamp(lens+offset,vec2(0.0),vec2(1.0))); total+=1.0;
  }}
  glass=mix(IN(clamp(lens,vec2(0.0),vec2(1.0))),glass/total,p_blur);
  float gradient=clamp((clamp(m2.y,0.0,0.2)+0.1)/2.0,0.0,1.0)+clamp((clamp(-m2.y,-1000.0,0.2)*rb3+0.1)/2.0,0.0,1.0);
  vec4 lighting=clamp(glass+vec4(rb1)*gradient+vec4(rb2)*0.3,0.0,1.0);
  return mix(base,lighting,transition);
}
